namespace BlazorNotifications.Services;

public class NotificationItem
{
    public int Id { get; set; }
    public string Message { get; set; } = string.Empty;
    public DateTime Timestamp { get; set; }
}

public class NotificationService
{
    private int _nextId = 1;
    private readonly List<NotificationItem> _notifications = new();
    private readonly Lock _lock = new();

    public NotificationService()
    {
        // Seed with initial fake data
        _notifications.Add(new NotificationItem { Id = _nextId++, Message = "Welcome to the app!", Timestamp = DateTime.UtcNow.AddMinutes(-10) });
        _notifications.Add(new NotificationItem { Id = _nextId++, Message = "Your profile was updated.", Timestamp = DateTime.UtcNow.AddMinutes(-5) });
        _notifications.Add(new NotificationItem { Id = _nextId++, Message = "New feature: dark mode is available.", Timestamp = DateTime.UtcNow.AddMinutes(-2) });
    }

    /// <summary>
    /// Gets all notifications currently available.
    /// </summary>
    public List<NotificationItem> GetAll()
    {
        lock (_lock)
        {
            return _notifications.ToList();
        }
    }

    /// <summary>
    /// Gets only notifications newer than the given ID.
    /// </summary>
    public List<NotificationItem> GetSince(int lastSeenId)
    {
        lock (_lock)
        {
            return _notifications.Where(n => n.Id > lastSeenId).ToList();
        }
    }

    /// <summary>
    /// Simulates new notifications arriving over time.
    /// Called internally to generate fake data.
    /// </summary>
    public void SimulateIncoming()
    {
        lock (_lock)
        {
            // ~30% chance of a new notification each poll
            if (Random.Shared.Next(100) < 30)
            {
                var messages = new[]
                {
                    "You have a new follower.",
                    "Someone liked your post.",
                    "Server maintenance scheduled.",
                    "Your export is ready to download.",
                    "A comment was added to your thread.",
                    "Security alert: new login detected."
                };
                _notifications.Add(new NotificationItem
                {
                    Id = _nextId++,
                    Message = messages[Random.Shared.Next(messages.Length)],
                    Timestamp = DateTime.UtcNow
                });
            }
        }
    }
}

@page "/notifications"
@rendermode InteractiveServer
@using BlazorNotifications.Services
@inject NotificationService NotificationSvc
@implements IDisposable

<PageTitle>Notifications</PageTitle>

<h1>Notifications <span class="badge bg-primary">@_notifications.Count</span></h1>

@if (_notifications.Count == 0)
{
    <p><em>No notifications yet.</em></p>
}
else
{
    <ul class="list-group">
        @foreach (var item in _notifications.OrderByDescending(n => n.Timestamp))
        {
            <li class="list-group-item d-flex justify-content-between align-items-start">
                <span>@item.Message</span>
                <small class="text-muted">@item.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    private List<NotificationItem> _notifications = new();
    private CancellationTokenSource? _cts;
    private int _lastSeenId;

    // Load initial data during SSR — this renders into the first HTML response.
    protected override void OnInitialized()
    {
        _notifications = NotificationSvc.GetAll();
        _lastSeenId = _notifications.Count > 0 ? _notifications.Max(n => n.Id) : 0;
    }

    // Called only once the component is interactive in the browser.
    // This is where we start the polling loop.
    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            try
            {
                await Task.Delay(TimeSpan.FromSeconds(5), ct);
            }
            catch (OperationCanceledException)
            {
                break;
            }

            // Simulate new data arriving on the server side
            NotificationSvc.SimulateIncoming();

            var newItems = NotificationSvc.GetSince(_lastSeenId);
            if (newItems.Count > 0)
            {
                _notifications.AddRange(newItems);
                _lastSeenId = newItems.Max(n => n.Id);
                await InvokeAsync(StateHasChanged);
            }
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

